5	use App\Jobs\Stripe\ExecuteCommissionPayoutJob;
6	use App\Models\Commerce\Order;
7	use App\Models\Core\Professional\Professional;
8	use App\Models\Retail\BrandStoreSettings;
9	use App\Models\Retail\CommissionPayout;
10	use App\Models\Retail\CommissionPayoutItem;
11	use App\Services\Notifications\NotificationPublisher;
12	use Illuminate\Support\Facades\DB;
13	use Illuminate\Support\Facades\Log;
14	use Stripe\Exception\ApiConnectionException;
15	use Stripe\Exception\ApiErrorException;
16	use Stripe\Exception\RateLimitException;
17	use Stripe\StripeClient;
18	
19	// V2: Core. Processes eligible commission payouts with hybrid funding (wallet balance first, card charge for shortfall). Transfers net amount to affiliate via Stripe Connect (80/20 split).
20	class CommissionPayoutService
21	{
22	    private StripeClient $stripe;
23	
24	    private NotificationPublisher $publisher;
25	
26	    private float $platformFeePercent;
27	
28	    private int $systemHoldDays;
29	
30	    private int $minHoldDays;
31	
32	    private int $gracePeriodDays;
33	
34	    public function __construct(?StripeClient $stripe = null, ?NotificationPublisher $publisher = null)
35	    {
36	        $this->stripe = $stripe ?? new StripeClient(config('services.stripe.secret_key'));
37	        $this->publisher = $publisher ?? app(NotificationPublisher::class);
38	        $this->platformFeePercent = config('partna.store.platform_fee_percent', 3);
39	        $this->systemHoldDays = max(0, (int) config('partna.store.payout_hold_days', 7));
40	        $this->minHoldDays = (int) config('partna.store.min_payout_hold_days', 7);
41	        // Clamp to [1, 365] — values outside this range produce nonsensical void_at timestamps.
42	        $this->gracePeriodDays = max(1, min(365, (int) config('partna.store.grace_period_days', 60)));
43	    }
44	
45	    /**
46	     * Main entry point: find all eligible unpaid commissions, batch them,
47	     * and dispatch a per-payout job for each. Returns dispatch counts only —
48	     * actual results are reported per-job via Horizon.
49	     *
50	     * @return array{batches_dispatched: int, batches_created: int, batches_requeued: int}
51	     */
52	    public function processEligiblePayouts(): array
53	    {
54	        $stats = [
55	            'batches_dispatched' => 0,
56	            'batches_created' => 0,
57	            'batches_requeued' => 0,
58	        ];
59	
60	        // Re-dispatch any in-flight batches. ExecuteCommissionPayoutJob's idempotent
61	        // resume logic handles collecting/transferring states safely.
62	        $existingPending = CommissionPayout::query()
63	            ->whereIn('status', ['pending', 'pending_funds', 'collecting', 'transferring'])
64	            ->whereNull('processed_at')
65	            ->where('eligible_after', '<=', now())
66	            ->orderBy('eligible_after')
67	            ->limit(500)
68	            ->get();
69	
70	        foreach ($existingPending as $pendingPayout) {
71	            ExecuteCommissionPayoutJob::dispatch($pendingPayout->id);
72	            $stats['batches_dispatched']++;
73	            $stats['batches_requeued']++;
74	        }
75	
76	        // Find all brands with unpaid approved orders, then apply per-brand hold days
77	        // to determine which orders have cleared their hold window.
78	        // Phase 3.5: source of truth moves from commission_movements to commerce.orders.
79	        $brandIds = Order::query()
80	            ->where('status', 'approved')
81	            ->whereNull('payout_id')
82	            ->where('refund_cents', 0)
83	            ->distinct()
84	            ->pluck('brand_professional_id');
85	
86	        // Pre-load brand store settings for hold-day lookups.
87	        $brandSettings = BrandStoreSettings::query()
88	            ->whereIn('professional_id', $brandIds)
89	            ->pluck('payout_hold_days', 'professional_id');
90	
91	        foreach ($brandIds as $brandId) {
92	            $holdDays = $this->resolveHoldDays($brandSettings[$brandId] ?? null);
93	            $cutoff = now()->utc()->subDays($holdDays);
94	
95	            $groups = Order::query()
96	                ->where('status', 'approved')
97	                ->whereNull('payout_id')
98	                ->where('refund_cents', 0)
99	                ->where('brand_professional_id', $brandId)
100	                ->where('occurred_at', '<=', $cutoff)
101	                ->select([
102	                    'brand_professional_id',
103	                    'affiliate_professional_id',
104	                    'currency_code',
105	                    DB::raw('SUM(commission_cents) as total_cents'),
106	                    DB::raw('COUNT(*) as entry_count'),
107	                ])
108	                ->groupBy('brand_professional_id', 'affiliate_professional_id', 'currency_code')
109	                ->having(DB::raw('SUM(commission_cents)'), '>', 0)
110	                ->get();
111	
112	            foreach ($groups as $group) {
113	                try {
114	                    $payout = $this->createPayoutBatch(
115	                        $group->brand_professional_id,
116	                        $group->affiliate_professional_id,
117	                        $group->currency_code,
118	                        $cutoff,
119	                    );
120	
121	                    if (! $payout) {
122	                        continue;
123	                    }
124	
125	                    $stats['batches_created']++;
126	                    ExecuteCommissionPayoutJob::dispatch($payout->id);
127	                    $stats['batches_dispatched']++;
128	                } catch (\Throwable $e) {
129	                    Log::error('Commission payout batch creation failed', [
130	                        'brand_id' => $group->brand_professional_id,
131	                        'affiliate_id' => $group->affiliate_professional_id,
132	                        'currency' => $group->currency_code,
133	                        'error' => $e instanceof ApiErrorException ? ($e->getStripeCode() ?? 'stripe_error') : get_class($e),
134	                    ]);
135	                }
136	            }
137	        }
138	
139	        return $stats;
140	    }
141	
142	    /**
143	     * Resolve the effective hold days for a brand.
144	     * Uses brand override if set, otherwise system default. Always >= system minimum.
145	     */
146	    private function resolveHoldDays(?int $brandPayoutHoldDays): int
147	    {
148	        $days = $brandPayoutHoldDays ?? $this->systemHoldDays;
149	
150	        return max($this->minHoldDays, $days);
151	    }
152	
153	    /**
154	     * Create a payout batch record and link all eligible orders.
155	     *
156	     * Phase 3.5+: reads from commerce.orders directly (not commission_movements).
157	     * Orders that are refunded after status='approved' have their status flipped to
158	     * 'partially_refunded'/'refunded', which the WHERE clause already excludes. Refunds
159	     * that arrive AFTER a payout is created are not reconciled in v1 — acceptable pre-beta;
160	     * tracked for Phase 4.
161	     */
162	    private function createPayoutBatch(
163	        string $brandId,
164	        string $affiliateId,
165	        string $currency,
166	        \DateTimeInterface $cutoff,
167	    ): ?CommissionPayout {
168	        // READ COMMITTED (PG default) — lockForUpdate() prevents a concurrent batch
169	        // from claiming the same orders between the SELECT and the payout_id stamp.
170	        return DB::transaction(function () use ($brandId, $affiliateId, $currency, $cutoff) {
171	            $orders = Order::query()
172	                ->where('status', 'approved')
173	                ->whereNull('payout_id')
174	                ->where('refund_cents', 0)
175	                ->where('brand_professional_id', $brandId)
176	                ->where('affiliate_professional_id', $affiliateId)
177	                ->where('currency_code', $currency)
178	                ->where('occurred_at', '<=', $cutoff)
179	                ->lockForUpdate()
180	                ->get();
181	
182	            if ($orders->isEmpty()) {
183	                return null;
184	            }
185	
186	            $grossCents = (int) $orders->sum('commission_cents');
187	            if ($grossCents <= 0) {
188	                return null;
189	            }
190	
191	            $platformFeeCents = (int) round($grossCents * $this->platformFeePercent / 100);
192	            $netPayoutCents = $grossCents - $platformFeeCents;
193	
194	            if ($netPayoutCents <= 0) {
195	                return null;
196	            }
197	
198	            // Per-payout grace window — 60d from creation. If the affiliate
199	            // hasn't activated Stripe Connect by then, VoidExpiredPayoutsJob
200	            // cancels this payout and clears the orders' payout_id stamps.
201	            // grace_period_days lives in config/sidest.php so ops can tune
202	            // the policy without a code release.
203	            // ledger_entry_count now counts orders included; column rename deferred to Phase 4.
204	            $payout = CommissionPayout::forceCreate([
205	                'brand_professional_id' => $brandId,
206	                'affiliate_professional_id' => $affiliateId,
207	                'status' => 'pending',
208	                'gross_commission_cents' => $grossCents,
209	                'platform_fee_cents' => $platformFeeCents,
210	                'net_payout_cents' => $netPayoutCents,
211	                'currency_code' => strtoupper($currency),
212	                'ledger_entry_count' => $orders->count(),
213	                'eligible_after' => $cutoff,
214	                'void_at' => now()->addDays($this->gracePeriodDays),
215	                'funding_source' => null,
216	            ]);
217	
218	            // Create one payout item per order; stamp orders.payout_id atomically
219	            // so the next sweep cannot double-claim these orders.
220	            foreach ($orders as $order) {
221	                CommissionPayoutItem::create([
222	                    'payout_id' => $payout->id,
223	                    'order_id' => $order->id,
224	                    'amount_cents' => $order->commission_cents,
225	                ]);
226	            }
227	
228	            Order::whereIn('id', $orders->pluck('id')->all())
229	                ->update(['payout_id' => $payout->id]);
230	
231	            return $payout;
232	        });
233	    }
234	
235	    /**
236	     * Process a single payout through the full 3-step flow with idempotent resume:
237	     *   1) Debit wallet balance (atomic with status update — crash-safe).
238	     *   2) Charge brand's card for any shortfall.
239	     *   3) Transfer net amount to affiliate via Stripe Connect.
240	     *
241	     * Each step checks the payout's current status before executing, so retries
242	     * (both Horizon automatic and admin manual) resume from where they left off
243	     * rather than restarting from scratch. This prevents double-debiting the wallet
244	     * and double-charging the brand's card.
245	     *
246	     * Return values:
247	     * - true:  completed
248	     * - null:  pending for funding/retry
249	     * - false: failed
250	     */
251	    public function processPayoutBatch(CommissionPayout $payout): ?bool
252	    {
253	        if ($payout->status === 'completed') {
254	            return true;
255	        }
256	
257	        $brand = Professional::find($payout->brand_professional_id);
258	        $affiliate = Professional::find($payout->affiliate_professional_id);
259	
260	        if (! $affiliate?->stripe_connect_account_id || $affiliate->stripe_connect_status !== 'active') {
261	            $this->markPendingFunding($payout, 'affiliate_not_connected', 'Affiliate Stripe Connect account is not active — holding for grace period');
262	
263	            return null;
264	        }
265	
266	        if (! $brand) {
267	            $this->failPayout($payout, 'brand_missing', 'Brand account was not found.');
268	
269	            return false;
270	        }
271	
272	        if (! $brand->stripe_customer_id || ! $brand->stripe_payment_method_id) {
273	            $this->markPendingFunding(
274	                $payout,
275	                'brand_payment_method_missing',
276	                'No payment method on file. Please add a card in your Stripe settings.',
277	            );
278	
279	            return null;
280	        }
281	
282	        $currencyUpper = strtoupper($payout->currency_code);
283	        $currencyLower = strtolower($currencyUpper);
284	        $amountToCollect = $payout->gross_commission_cents;
285	
286	        // Idempotency key suffix used only for PaymentIntents — retry_count is incremented
287	        // on each admin manual retry so a fresh PI is created rather than returning a
288	        // refunded/failed one from within the 24-hour idempotency TTL window.
289	        // Transfers intentionally use a stable key (no suffix) so Stripe returns the same
290	        // transfer on any retry, preventing a duplicate payout if the transfer succeeded
291	        // but the HTTP response was lost before the ID could be recorded.
292	        $retryKey = '_r'.$payout->retry_count;
293	
294	        // Step 1: Wallet debit — or resume from recorded state
295	        //
296	        // The debit and the status update are wrapped in a single DB::transaction
297	        // so a process crash between them can't leave the wallet reduced but the
298	        // payout record still showing 'pending' (which would cause a double-debit on retry).
299	        $walletDebitCents = 0;
300	        $chargeAmountCents = $amountToCollect;
301	
302	        if (in_array($payout->status, ['collecting', 'collected', 'transferring'], true)) {
303	            // Wallet debit already committed in a previous run — read from DB, don't re-debit.
304	            $walletDebitCents = (int) ($payout->wallet_debit_cents ?? 0);
305	            $chargeAmountCents = (int) ($payout->charge_cents ?? $amountToCollect);
306	        } else {
307	            // READ COMMITTED (PG default) — the payout status update and wallet debit
308	            // are atomic here; lockForUpdate() inside debitBrandManualBalancePartial
309	            // guards against concurrent debits on the wallet row itself.
310	            $hasCurrencyMismatch = false;
311	            DB::transaction(function () use ($payout, $brand, $amountToCollect, $currencyUpper, &$walletDebitCents, &$chargeAmountCents, &$hasCurrencyMismatch): void {
312	                $walletDebitCents = $this->debitBrandManualBalancePartial($brand->id, $amountToCollect, $currencyUpper, $hasCurrencyMismatch);
313	
314	                // Wallet has balance but in the wrong currency — abort without charging card.
315	                // markPendingFunding and notification happen outside the transaction below.
316	                if ($hasCurrencyMismatch) {
317	                    return;
318	                }
319	
320	                $chargeAmountCents = $amountToCollect - $walletDebitCents;
321	
322	                $fundingSource = 'card';
323	                if ($walletDebitCents > 0 && $chargeAmountCents > 0) {
324	                    $fundingSource = 'wallet_and_card';
325	                } elseif ($walletDebitCents > 0) {
326	                    $fundingSource = 'wallet';
327	                }
328	
329	                $payout->forceFill([
330	                    'status' => 'collecting',
331	                    'funding_source' => $fundingSource,
332	                    'wallet_debit_cents' => $walletDebitCents,
333	                    'charge_cents' => $chargeAmountCents,
334	                    'failure_code' => null,
335	                    'failure_reason' => null,
336	                ])->save();
337	            });
338	
339	            if ($hasCurrencyMismatch) {
340	                $walletCurrency = strtoupper((string) ($brand->stripe_manual_balance_currency ?? 'unknown'));
341	                $this->markPendingFunding(
342	                    $payout,
343	                    'wallet_currency_mismatch',
344	                    "Wallet balance is in {$walletCurrency} but payout requires {$currencyUpper}. Please contact support to resolve.",
345	                );
346	
347	                $this->publisher->publish(
348	                    professionalId: $payout->brand_professional_id,
349	                    frontendType: 'Warning',
350	                    category: 'commissions',
351	                    title: 'Commission payout on hold',
352	                    body: sprintf(
353	                        'A commission payout of %s could not be processed because your wallet balance is in %s. Please contact support to resolve the currency mismatch.',
354	                        $this->formatMoney($payout->gross_commission_cents, $payout->currency_code),
355	                        $walletCurrency,
356	                    ),
357	                    dedupeKey: "wallet_currency_mismatch.{$payout->id}",
358	                    ctaUrl: '/account/settings?section=wallet',
359	                );
360	
361	                return null;
362	            }
363	        }
364	
365	        // Step 2: Charge brand's card for the shortfall (if any)
366	        $latestChargeId = null;
367	
368	        if (in_array($payout->status, ['collected', 'transferring'], true)) {
369	            // PaymentIntent already succeeded in a previous run.
370	            // Retrieve the charge ID so we can use source_transaction on the transfer.
371	            if ($payout->stripe_payment_intent_id && $chargeAmountCents > 0) {
372	                $pi = $this->stripe->paymentIntents->retrieve($payout->stripe_payment_intent_id);
373	                $latestChargeId = $this->extractLatestChargeId($pi);
374	            }
375	        } elseif ($chargeAmountCents > 0) {
376	            try {
377	                $paymentIntent = $this->stripe->paymentIntents->create([
378	                    'amount' => $chargeAmountCents,
379	                    'currency' => $currencyLower,
380	                    'customer' => $brand->stripe_customer_id,
381	                    'payment_method' => $brand->stripe_payment_method_id,
382	                    'confirm' => true,
383	                    'off_session' => true,
384	                    'description' => "Commission payout #{$payout->id}",
385	                    'metadata' => [
386	                        'sidest_payout_id' => $payout->id,
387	                        'brand_id' => $brand->id,
388	                        'affiliate_id' => $affiliate->id,
389	                    ],
390	                ], ['idempotency_key' => 'pi_'.$payout->id.$retryKey]);
391	
392	                if ($paymentIntent->status !== 'succeeded') {
393	                    // SCA required — cancel the PI so the idempotency key is freed for the next
394	                    // attempt. Without cancellation the same key returns this stuck PI for 24h.
395	                    try {
396	                        $this->stripe->paymentIntents->cancel($paymentIntent->id);
397	                    } catch (\Throwable) {
398	                        // Non-critical: PI may already be in a terminal state
399	                    }
400	                    if ($walletDebitCents > 0) {
401	                        $this->creditBrandManualBalance($brand->id, $walletDebitCents, $currencyUpper);
402	                    }
403	                    $this->markPendingFunding($payout, 'charge_requires_action', 'Card charge requires authentication.');
404	
405	                    return null;
406	                }
407	
408	                $latestChargeId = $this->extractLatestChargeId($paymentIntent);
409	
410	                $payout->forceFill([
411	                    'stripe_payment_intent_id' => $paymentIntent->id,
412	                    'status' => 'collected',
413	                ])->save();
414	            } catch (ApiConnectionException|RateLimitException $e) {
415	                // Transient error — re-throw so Horizon retries with backoff.
416	                // Wallet debit is already committed in 'collecting' status; the
417	                // idempotent resume will skip re-debiting on the next attempt.
418	                throw $e;
419	            } catch (ApiErrorException $e) {
420	                // Terminal card failure (declined, invalid PM, SCA permanently blocked, etc.)
421	                if ($walletDebitCents > 0) {
422	                    $this->creditBrandManualBalance($brand->id, $walletDebitCents, $currencyUpper);
423	                }
424	                $this->markPendingFunding($payout, 'charge_failed', $e->getStripeCode() ?? 'stripe_error');
425	
426	                return null;
427	            }
428	        } else {
429	            // Fully funded by wallet — only advance status if not already past this step
430	            if (! in_array($payout->status, ['collected', 'transferring'], true)) {
431	                $payout->forceFill(['status' => 'collected'])->save();
432	            }
433	        }
434	
435	        // Step 3: Transfer net amount to the affiliate's Connect account
436	        try {
437	            if ($payout->status !== 'transferring') {
438	                $payout->forceFill(['status' => 'transferring'])->save();
439	            }
440	
441	            // Guard: skip transfer creation if a prior run already recorded the ID
442	            // (e.g. the transfer was saved but the server crashed before marking complete).
443	            if (! $payout->stripe_transfer_id) {
444	                $transferPayload = [
445	                    'amount' => $payout->net_payout_cents,
446	                    'currency' => $currencyLower,
447	                    'destination' => $affiliate->stripe_connect_account_id,
448	                    'description' => "Commission payout #{$payout->id} to {$affiliate->display_name}",
449	                    'metadata' => [
450	                        'sidest_payout_id' => $payout->id,
451	                        'brand_id' => $brand->id,
452	                        'affiliate_id' => $affiliate->id,
453	                    ],
454	                ];
455	
456	                if ($latestChargeId) {
457	                    $transferPayload['source_transaction'] = $latestChargeId;
458	                }
459	
460	                $transfer = $this->stripe->transfers->create(
461	                    $transferPayload,
462	                    // Stable key — no retry_count suffix. Stripe returns the same transfer
463	                    // on any retry (including admin retries that increment retry_count),
464	                    // preventing a duplicate payout when the transfer succeeded but the
465	                    // response was lost before stripe_transfer_id could be recorded.
466	                    ['idempotency_key' => 'tr_'.$payout->id]
467	                );
468	
469	                // Persist stripe_transfer_id before the completion record. If the process
470	                // crashes between these two saves, the guard above prevents re-creation.
471	                $payout->forceFill(['stripe_transfer_id' => $transfer->id])->save();
472	            }
473	
474	            $payout->forceFill([
475	                'status' => 'completed',
476	                'processed_at' => now(),
477	                'failure_code' => null,
478	                'failure_reason' => null,
479	            ])->save();
480	
481	            Log::info('Commission payout completed', [
482	                'payout_id' => $payout->id,
483	                'gross_cents' => $payout->gross_commission_cents,
484	                'wallet_debit_cents' => $walletDebitCents,
485	                'charge_cents' => $chargeAmountCents,
486	                'platform_fee_cents' => $payout->platform_fee_cents,
487	                'net_cents' => $payout->net_payout_cents,
488	                'funding_source' => $payout->funding_source,
489	                'currency' => $payout->currency_code,
490	            ]);
491	
492	            return true;
493	        } catch (ApiConnectionException|RateLimitException $e) {
494	            // Transient error — re-throw so Horizon retries from 'transferring' status.
495	            // Wallet and charge are NOT reversed. The stable transfer idempotency key
496	            // and the stripe_transfer_id guard above together ensure no duplicate transfer
497	            // is created if the original request succeeded but the response was lost.
498	            throw $e;
499	        } catch (ApiErrorException $e) {
500	            // Terminal transfer failure — credit wallet back, then attempt to auto-refund.
501	            if ($walletDebitCents > 0) {
502	                $this->creditBrandManualBalance($brand->id, $walletDebitCents, $currencyUpper);
503	            }
504	
505	            $failureCode = 'transfer_failed';
506	
507	            if ($payout->stripe_payment_intent_id && $chargeAmountCents > 0) {
508	                try {
509	                    $this->stripe->refunds->create([
510	                        'payment_intent' => $payout->stripe_payment_intent_id,
511	                    ], ['idempotency_key' => "rf_{$payout->id}_{$payout->stripe_payment_intent_id}"]);
512	                    $failureCode = 'transfer_failed_refunded';
513	                    // Clear PI ID so an admin retry can create a fresh PaymentIntent
514	                    // (same idempotency key within 24h would return the now-refunded PI).
515	                    $payout->forceFill(['stripe_payment_intent_id' => null])->save();
516	                } catch (\Throwable $refundEx) {
517	                    // Auto-refund failed — the brand may still be charged. Flag for manual resolution.
518	                    $failureCode = 'transfer_failed_refund_needed';
519	                    $payout->forceFill(['needs_manual_refund' => true])->save();
520	                    Log::error('Auto-refund after transfer failure failed — manual action required', [
521	                        'payout_id' => $payout->id,
522	                        'payment_intent_id' => $payout->stripe_payment_intent_id,
523	                        'transfer_error' => $e->getStripeCode() ?? 'stripe_error',
524	                        'refund_error' => $refundEx instanceof ApiErrorException ? ($refundEx->getStripeCode() ?? 'stripe_error') : get_class($refundEx),
525	                    ]);
526	                }
527	            }
528	
529	            $this->failPayout($payout, $failureCode, $e->getStripeCode() ?? 'stripe_error');
530	
531	            return false;
532	        }
533	    }
534	
535	    /**
536	     * Debit the brand's wallet balance, up to the requested amount (partial OK).
537	     * Returns the actual amount debited (0 if no balance available).
538	     *
539	     * Sets $hasCurrencyMismatch=true when the wallet has a positive balance but in a
540	     * different currency than $currencyCode — caller must treat this as a hard stop,
541	     * not a zero-balance case, to avoid silently charging the full amount to the card.
542	     */
543	    private function debitBrandManualBalancePartial(string $brandId, int $requestedCents, string $currencyCode, bool &$hasCurrencyMismatch = false): int
544	    {
545	        if ($requestedCents <= 0) {
546	            return 0;
547	        }
548	
549	        // READ COMMITTED (PG default) — lockForUpdate() on the professional row
550	        // serialises concurrent debits; no higher isolation level is required.
551	        return DB::transaction(function () use ($brandId, $requestedCents, $currencyCode, &$hasCurrencyMismatch) {
552	            $brand = Professional::query()
553	                ->whereKey($brandId)
554	                ->lockForUpdate()
555	                ->first();
556	
557	            if (! $brand) {
558	                return 0;
559	            }
560	
561	            $balance = max(0, (int) ($brand->stripe_manual_balance_cents ?? 0));
562	            $walletCurrency = strtoupper((string) ($brand->stripe_manual_balance_currency ?: $currencyCode));
563	
564	            if ($walletCurrency !== strtoupper($currencyCode)) {
565	                // Only flag as a mismatch when there's actual balance in the wrong currency.
566	                // An empty wallet with any currency is just "no funds" — not a mismatch.
567	                if ($balance > 0) {
568	                    $hasCurrencyMismatch = true;
569	                }
570	
571	                return 0;
572	            }
573	
574	            if ($balance <= 0) {
575	                return 0;
576	            }
577	
578	            $debit = min($balance, $requestedCents);
579	            $brand->stripe_manual_balance_cents = $balance - $debit;
580	            $brand->save();
581	
582	            return $debit;
583	        });
584	    }
585	
586	    public function creditBrandManualBalance(string $brandId, int $amountCents, string $currencyCode): void
587	    {
588	        if ($amountCents <= 0) {
589	            return;
590	        }
591	
592	        // READ COMMITTED (PG default) — lockForUpdate() serialises concurrent credits.
593	        DB::transaction(function () use ($brandId, $amountCents, $currencyCode) {
594	            $brand = Professional::query()
595	                ->whereKey($brandId)
596	                ->lockForUpdate()
597	                ->first();
598	
599	            if (! $brand) {
600	                return;
601	            }
602	
603	            $balance = (int) ($brand->stripe_manual_balance_cents ?? 0);
604	            $brand->stripe_manual_balance_cents = $balance + $amountCents;
605	            $brand->stripe_manual_balance_currency = strtoupper((string) ($brand->stripe_manual_balance_currency ?: $currencyCode));
606	            $brand->save();
607	        });
608	    }
609	
610	    private function extractLatestChargeId(object $paymentIntent): ?string
611	    {
612	        if (is_string($paymentIntent->latest_charge ?? null) && $paymentIntent->latest_charge !== '') {
613	            return $paymentIntent->latest_charge;
614	        }
615	
616	        if (is_object($paymentIntent->latest_charge ?? null) && is_string($paymentIntent->latest_charge->id ?? null)) {
617	            return $paymentIntent->latest_charge->id;
618	        }
619	
620	        if (is_object($paymentIntent->charges ?? null) && is_array($paymentIntent->charges->data ?? null)) {
621	            foreach ($paymentIntent->charges->data as $charge) {
622	                if (is_object($charge) && is_string($charge->id ?? null) && $charge->id !== '') {
623	                    return $charge->id;
624	                }
625	            }
626	        }
627	
628	        return null;
629	    }
630	
631	    private function markPendingFunding(CommissionPayout $payout, string $code, string $reason): void
632	    {
633	        $payout->forceFill([
634	            'status' => 'pending_funds',
635	            'failure_code' => $code,
636	            'failure_reason' => $reason,
637	            'processed_at' => null,
638	        ])->save();
639	
640	        Log::notice('Commission payout pending funding', [
641	            'payout_id' => $payout->id,
642	            'code' => $code,
643	            'reason' => $reason,
644	        ]);
645	    }
646	
647	    private function failPayout(CommissionPayout $payout, string $code, string $reason): void
648	    {
649	        $payout->forceFill([
650	            'status' => 'failed',
651	            'failure_code' => $code,
652	            'failure_reason' => $reason,
653	        ])->save();
654	
655	        Log::warning('Commission payout failed', [
656	            'payout_id' => $payout->id,
657	            'code' => $code,
658	            'reason' => $reason,
659	        ]);
660	    }
661	
662	    /**
663	     * Manually retry a stuck payout batch (admin endpoint).
664	     *
665	     * Increments retry_count so a fresh Stripe idempotency key is used —
666	     * prevents Stripe returning a refunded/failed PI from within the 24h TTL window.
667	     *
668	     * Blocked for transfer_failed_refund_needed: the auto-refund itself failed, so
669	     * the brand may still be charged. Manual verification is required before retrying.
670	     *
671	     * Runs synchronously so the admin sees the result immediately.
672	     */
673	    public function retryPayout(CommissionPayout $payout): bool
674	    {
675	        if (! in_array($payout->status, ['failed', 'pending', 'pending_funds'], true)) {
676	            return false;
677	        }
678	
679	        // Auto-refund failed — manual verification required before retrying to avoid double-charging.
680	        if ($payout->failure_code === 'transfer_failed_refund_needed') {
681	            return false;
682	        }
683	
684	        // If the wallet was already debited in a previous run, resume from 'collecting'
685	        // so processPayoutBatch() enters its idempotent resume branch and skips
686	        // re-debiting. Resetting to 'pending' would bypass that branch and double-debit.
687	        $resumeStatus = ((int) ($payout->wallet_debit_cents ?? 0)) > 0 ? 'collecting' : 'pending';
688	
689	        $payout->forceFill([
690	            'status' => $resumeStatus,
691	            'failure_code' => null,
692	            'failure_reason' => null,
693	            'needs_manual_refund' => false,
694	            'retry_count' => ($payout->retry_count ?? 0) + 1,
695	        ])->save();
696	
697	        return $this->processPayoutBatch($payout) === true;
698	    }
699	
700	    private function formatMoney(int $cents, string $currencyCode): string
701	    {
702	        $prefix = match (strtoupper($currencyCode)) {
703	            'USD' => '$',
704	            'GBP' => '£',
705	            'EUR' => '€',
706	            'AUD' => 'A$',
707	            default => strtoupper($currencyCode).' ',
708	        };
709	
710	        return $prefix.number_format($cents / 100, 2, '.', ',');
711	    }
712	
713	    /**
714	     * Get payout summary for a professional (as brand or affiliate).
715	     */
716	    public function getPayoutSummary(Professional $professional): array
717	    {
718	        $asBrand = CommissionPayout::query()
719	            ->where('brand_professional_id', $professional->id)
720	            ->selectRaw('status, COUNT(*) as count, SUM(gross_commission_cents) as total_cents')
721	            ->groupBy('status')
722	            ->get()
723	            ->keyBy('status');
724	
725	        $asAffiliate = CommissionPayout::query()
726	            ->where('affiliate_professional_id', $professional->id)
727	            ->selectRaw('status, COUNT(*) as count, SUM(net_payout_cents) as total_cents')
728	            ->groupBy('status')
729	            ->get()
730	            ->keyBy('status');
731	
732	        return [
733	            'as_brand' => $asBrand,
734	            'as_affiliate' => $asAffiliate,
735	        ];
736	    }
737	}
