19	// V2: Core. Processes eligible commission payouts with hybrid funding (wallet balance first, card charge for shortfall). Transfers net amount to affiliate via Stripe Connect (80/20 split).
20	class CommissionPayoutService
21	{
22	    private StripeClient $stripe;
23	
24	    private NotificationPublisher $publisher;
25	
26	    private float $platformFeePercent;
