142	    /**
143	     * Resolve the effective hold days for a brand.
144	     * Uses brand override if set, otherwise system default. Always >= system minimum.
145	     */
146	    private function resolveHoldDays(?int $brandPayoutHoldDays): int
147	    {
148	        $days = $brandPayoutHoldDays ?? $this->systemHoldDays;
149	
150	        return max($this->minHoldDays, $days);
151	    }
152	
153	    /**
154	     * Create a payout batch record and link all eligible orders.
155	     *
156	     * Phase 3.5+: reads from commerce.orders directly (not commission_movements).
157	     * Orders that are refunded after status='approved' have their status flipped to
158	     * 'partially_refunded'/'refunded', which the WHERE clause already excludes. Refunds
159	     * that arrive AFTER a payout is created are not reconciled in v1 — acceptable pre-beta;
160	     * tracked for Phase 4.
161	     */
162	    private function createPayoutBatch(
163	        string $brandId,
164	        string $affiliateId,
165	        string $currency,
166	        \DateTimeInterface $cutoff,
167	    ): ?CommissionPayout {
168	        // READ COMMITTED (PG default) — lockForUpdate() prevents a concurrent batch
169	        // from claiming the same orders between the SELECT and the payout_id stamp.
170	        return DB::transaction(function () use ($brandId, $affiliateId, $currency, $cutoff) {
171	            $orders = Order::query()
172	                ->where('status', 'approved')
173	                ->whereNull('payout_id')
174	                ->where('refund_cents', 0)
175	                ->where('brand_professional_id', $brandId)
176	                ->where('affiliate_professional_id', $affiliateId)
177	                ->where('currency_code', $currency)
178	                ->where('occurred_at', '<=', $cutoff)
179	                ->lockForUpdate()
180	                ->get();
181	
182	            if ($orders->isEmpty()) {
183	                return null;
184	            }
185	
186	            $grossCents = (int) $orders->sum('commission_cents');
187	            if ($grossCents <= 0) {
188	                return null;
189	            }
190	
191	            $platformFeeCents = (int) round($grossCents * $this->platformFeePercent / 100);
192	            $netPayoutCents = $grossCents - $platformFeeCents;
193	
194	            if ($netPayoutCents <= 0) {
195	                return null;
196	            }
197	
198	            // Per-payout grace window — 60d from creation. If the affiliate
199	            // hasn't activated Stripe Connect by then, VoidExpiredPayoutsJob
