210	                'net_payout_cents' => $netPayoutCents,
211	                'currency_code' => strtoupper($currency),
212	                'ledger_entry_count' => $orders->count(),
213	                'eligible_after' => $cutoff,
214	                'void_at' => now()->addDays($this->gracePeriodDays),
