235	    /**
236	     * Process a single payout through the full 3-step flow with idempotent resume:
237	     *   1) Debit wallet balance (atomic with status update — crash-safe).
238	     *   2) Charge brand's card for any shortfall.
239	     *   3) Transfer net amount to affiliate via Stripe Connect.
240	     *
241	     * Each step checks the payout's current status before executing, so retries
242	     * (both Horizon automatic and admin manual) resume from where they left off
243	     * rather than restarting from scratch. This prevents double-debiting the wallet
244	     * and double-charging the brand's card.
245	     *
246	     * Return values:
247	     * - true:  completed
248	     * - null:  pending for funding/retry
249	     * - false: failed
250	     */
251	    public function processPayoutBatch(CommissionPayout $payout): ?bool
252	    {
253	        if ($payout->status === 'completed') {
254	            return true;
255	        }
256	
257	        $brand = Professional::find($payout->brand_professional_id);
258	        $affiliate = Professional::find($payout->affiliate_professional_id);
