261	            $this->markPendingFunding($payout, 'affiliate_not_connected', 'Affiliate Stripe Connect account is not active — holding for grace period');
262	
263	            return null;
264	        }
265	
266	        if (! $brand) {
267	            $this->failPayout($payout, 'brand_missing', 'Brand account was not found.');
268	
269	            return false;
270	        }
271	
272	        if (! $brand->stripe_customer_id || ! $brand->stripe_payment_method_id) {
273	            $this->markPendingFunding(
274	                $payout,
275	                'brand_payment_method_missing',
276	                'No payment method on file. Please add a card in your Stripe settings.',
277	            );
