662	    /**
663	     * Manually retry a stuck payout batch (admin endpoint).
664	     *
665	     * Increments retry_count so a fresh Stripe idempotency key is used —
666	     * prevents Stripe returning a refunded/failed PI from within the 24h TTL window.
667	     *
668	     * Blocked for transfer_failed_refund_needed: the auto-refund itself failed, so
669	     * the brand may still be charged. Manual verification is required before retrying.
670	     *
671	     * Runs synchronously so the admin sees the result immediately.
672	     */
673	    public function retryPayout(CommissionPayout $payout): bool
674	    {
675	        if (! in_array($payout->status, ['failed', 'pending', 'pending_funds'], true)) {
676	            return false;
677	        }
678	
679	        // Auto-refund failed — manual verification required before retrying to avoid double-charging.
680	        if ($payout->failure_code === 'transfer_failed_refund_needed') {
681	            return false;
682	        }
683	
684	        // If the wallet was already debited in a previous run, resume from 'collecting'
685	        // so processPayoutBatch() enters its idempotent resume branch and skips
686	        // re-debiting. Resetting to 'pending' would bypass that branch and double-debit.
687	        $resumeStatus = ((int) ($payout->wallet_debit_cents ?? 0)) > 0 ? 'collecting' : 'pending';
688	
689	        $payout->forceFill([
690	            'status' => $resumeStatus,
691	            'failure_code' => null,
692	            'failure_reason' => null,
693	            'needs_manual_refund' => false,
694	            'retry_count' => ($payout->retry_count ?? 0) + 1,
695	        ])->save();
696	
697	        return $this->processPayoutBatch($payout) === true;
698	    }
