28	    ) {}
29	
30	    /**
31	     * GET /staff/commission-payouts
32	     *
33	     * List all payouts platform-wide. Query params:
34	     *   status            — pending|processing|completed|failed|...
35	     *   needs_manual_refund — true|false (filter for stuck double-failure cases)
36	     *   per_page          — default 25, max 100
37	     */
38	    public function index(Request $request): JsonResponse
39	    {
40	        $perPage = $this->normalizePerPage($request, 25, 100);
41	        $status = $request->query('status');
42	        $needsManualRefund = $request->query('needs_manual_refund');
43	
