87	    public function retry(Request $request, CommissionPayout $payout): JsonResponse
88	    {
89	        if (! in_array($payout->status, ['failed', 'pending'], true)) {
90	            return $this->error(
91	                "Payout is in status '{$payout->status}' and cannot be retried. Only 'failed' or 'pending' batches are retryable.",
92	                422
93	            );
