100	                'This payout requires manual refund verification. Confirm the brand has been refunded in Stripe, then call POST /staff/commission-payouts/{payout}/acknowledge-manual-refund before retrying.',
101	                422
102	            );
103	        }
104	
105	        // retryPayout() resets status, clears failure_code/reason, and runs
106	        // processPayoutBatch synchronously. Transient Stripe errors re-throw
107	        // (Horizon backoff design) — surface them as 503 so staff know to retry.
108	        try {
109	            $this->payoutService->retryPayout($payout);
110	        } catch (ApiConnectionException|RateLimitException $e) {
111	            return $this->error('Stripe is temporarily unavailable. Please try again in a moment.', 503);
112	        }
113	        $payout->refresh();
114	
115	        return $this->success([
116	            'id' => $payout->id,
117	            'status' => $payout->status,
118	            'failure_code' => $payout->failure_code,
119	            'failure_reason' => $payout->failure_reason,
120	            'needs_manual_refund' => (bool) $payout->needs_manual_refund,
121	            'processed_at' => $payout->processed_at?->toIso8601String(),
122	            'net_payout_cents' => (int) $payout->net_payout_cents,
123	            'currency_code' => (string) $payout->currency_code,
124	        ]);
125	    }
126	
127	    /**
128	     * POST /staff/commission-payouts/{payout}/acknowledge-manual-refund
129	     *
130	     * Staff acknowledges they have manually issued (or confirmed the absence of)
131	     * the Stripe refund for a payout where the auto-refund failed after a transfer
132	     * failure. This clears the needs_manual_refund block and makes the payout
133	     * retryable via the /retry endpoint.
134	     *
135	     * The stripe_payment_intent_id is cleared so the retry creates a fresh
136	     * PaymentIntent — reusing the same PI after a manual refund would hit
137	     * Stripe's 24h idempotency window and return the already-refunded intent.
138	     *
139	     * @return JsonResponse {
140	     *                      data: {
141	     *                      id: string,
142	     *                      status: string,
143	     *                      failure_code: string|null,
144	     *                      needs_manual_refund: false
145	     *                      }
146	     *                      }
147	     */
148	    public function acknowledgeManualRefund(Request $request, CommissionPayout $payout): JsonResponse
149	    {
150	        if (! $payout->needs_manual_refund) {
151	            return $this->error('This payout does not have a pending manual refund flag.', 422);
152	        }
153	
154	        $payout->forceFill([
155	            'needs_manual_refund' => false,
156	            // failure_code stays 'transfer_failed_refund_needed' → change to
157	            // 'transfer_failed' so retryPayout() no longer has a code-based block.
158	            'failure_code' => 'transfer_failed',
159	            // Clear PI so retry creates a fresh PaymentIntent (avoids Stripe
160	            // returning the already-refunded PI within the 24h idempotency TTL).
161	            'stripe_payment_intent_id' => null,
162	        ])->save();
163	
164	        return $this->success([
165	            'id' => $payout->id,
166	            'status' => $payout->status,
167	            'failure_code' => $payout->failure_code,
168	            'needs_manual_refund' => false,
169	        ]);
170	    }
171	}
